-- Generated by hfsynth. SQLite-compatible; works on PostgreSQL with minor type changes.

CREATE TABLE "category" (
  category_code TEXT NOT NULL,
  category_name TEXT NOT NULL,
  parent_code TEXT,
  category_type TEXT NOT NULL CHECK (category_type IN ('EXPENSE','INCOME','TRANSFER','SYSTEM')),
  is_spending INTEGER NOT NULL,
  is_budgetable INTEGER NOT NULL,
  PRIMARY KEY (category_code),
  FOREIGN KEY (parent_code) REFERENCES "category"(category_code)
);

CREATE TABLE "user_profile" (
  user_id TEXT NOT NULL,
  age_band TEXT NOT NULL CHECK (age_band IN ('18-24','25-34','35-44','45-54','55-64','65+')),
  region_code TEXT NOT NULL CHECK (region_code IN ('US-EAST','US-CENTRAL','US-MOUNTAIN','US-WEST')),
  home_timezone TEXT NOT NULL CHECK (home_timezone IN ('America/New_York','America/Chicago','America/Denver','America/Los_Angeles')),
  household_size INTEGER NOT NULL,
  monthly_net_income NUMERIC NOT NULL,
  pay_frequency TEXT NOT NULL CHECK (pay_frequency IN ('BIWEEKLY','SEMI_MONTHLY','MONTHLY')),
  signup_date TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('ACTIVE')),
  PRIMARY KEY (user_id)
);

CREATE TABLE "account" (
  account_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  account_type TEXT NOT NULL CHECK (account_type IN ('CHECKING','SAVINGS','CREDIT_CARD')),
  currency TEXT NOT NULL CHECK (currency IN ('USD')),
  open_date TEXT NOT NULL,
  opening_balance NUMERIC NOT NULL,
  closing_balance NUMERIC NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('ACTIVE')),
  PRIMARY KEY (account_id),
  FOREIGN KEY (user_id) REFERENCES "user_profile"(user_id)
);

CREATE TABLE "merchant" (
  merchant_id TEXT NOT NULL,
  canonical_name TEXT NOT NULL,
  merchant_type TEXT NOT NULL CHECK (merchant_type IN ('RETAILER','RESTAURANT','TRANSPORT','FUEL','ENTERTAINMENT','HEALTHCARE','TRAVEL','EDUCATION','MULTI_CATEGORY','SUBSCRIPTION','UTILITY','INSURER','LANDLORD','EMPLOYER')),
  mcc TEXT,
  default_category_code TEXT NOT NULL,
  is_multi_category INTEGER NOT NULL,
  opened_date TEXT NOT NULL,
  closed_date TEXT,
  status TEXT NOT NULL CHECK (status IN ('ACTIVE','CLOSED')),
  PRIMARY KEY (merchant_id),
  FOREIGN KEY (default_category_code) REFERENCES "category"(category_code)
);

CREATE TABLE "merchant_alias" (
  alias_id TEXT NOT NULL,
  merchant_id TEXT NOT NULL,
  alias_text TEXT NOT NULL,
  alias_type TEXT NOT NULL CHECK (alias_type IN ('FULL','SHORT_NAME')),
  PRIMARY KEY (alias_id),
  FOREIGN KEY (merchant_id) REFERENCES "merchant"(merchant_id)
);

CREATE TABLE "merchant_category" (
  merchant_id TEXT NOT NULL,
  category_code TEXT NOT NULL,
  share NUMERIC NOT NULL,
  is_default INTEGER NOT NULL,
  PRIMARY KEY (merchant_id, category_code),
  FOREIGN KEY (merchant_id) REFERENCES "merchant"(merchant_id),
  FOREIGN KEY (category_code) REFERENCES "category"(category_code)
);

CREATE TABLE "category_rule" (
  rule_id TEXT NOT NULL,
  rule_type TEXT NOT NULL CHECK (rule_type IN ('TXN_TYPE','KEYWORD','MERCHANT_ALIAS','FALLBACK')),
  match_value TEXT NOT NULL,
  category_code TEXT,
  priority INTEGER NOT NULL,
  effective_from TEXT NOT NULL,
  effective_to TEXT,
  status TEXT NOT NULL CHECK (status IN ('ACTIVE','RETIRED')),
  PRIMARY KEY (rule_id),
  FOREIGN KEY (category_code) REFERENCES "category"(category_code)
);

CREATE TABLE "transaction" (
  txn_id TEXT NOT NULL,
  account_id TEXT NOT NULL,
  merchant_id TEXT,
  category_code TEXT NOT NULL,
  category_rule_id TEXT NOT NULL,
  txn_ts_utc TEXT NOT NULL,
  utc_offset_min INTEGER NOT NULL,
  txn_date TEXT NOT NULL,
  descriptor TEXT NOT NULL,
  amount NUMERIC NOT NULL,
  currency TEXT NOT NULL CHECK (currency IN ('USD')),
  txn_type TEXT NOT NULL CHECK (txn_type IN ('PURCHASE','REFUND','RECURRING_DEBIT','INCOME','TRANSFER_OUT','TRANSFER_IN')),
  channel TEXT NOT NULL CHECK (channel IN ('CARD_POS','CARD_ONLINE','ACH','BILL_PAY','TRANSFER')),
  transfer_group_id TEXT,
  refund_of_txn_id TEXT,
  balance_after NUMERIC NOT NULL,
  PRIMARY KEY (txn_id),
  FOREIGN KEY (account_id) REFERENCES "account"(account_id),
  FOREIGN KEY (merchant_id) REFERENCES "merchant"(merchant_id),
  FOREIGN KEY (category_code) REFERENCES "category"(category_code),
  FOREIGN KEY (category_rule_id) REFERENCES "category_rule"(rule_id),
  FOREIGN KEY (refund_of_txn_id) REFERENCES "transaction"(txn_id)
);

CREATE TABLE "recurring_series" (
  series_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  account_id TEXT NOT NULL,
  counterparty_account_id TEXT,
  merchant_id TEXT,
  series_type TEXT NOT NULL CHECK (series_type IN ('SALARY','RENT','UTILITY','INSURANCE','SUBSCRIPTION','SAVINGS_TRANSFER')),
  category_code TEXT NOT NULL,
  cadence TEXT NOT NULL CHECK (cadence IN ('BIWEEKLY','SEMI_MONTHLY','MONTHLY','ANNUAL')),
  anchor_date TEXT NOT NULL,
  start_date TEXT NOT NULL,
  end_date TEXT,
  direction TEXT NOT NULL CHECK (direction IN ('CREDIT','DEBIT','TRANSFER')),
  amount_type TEXT NOT NULL CHECK (amount_type IN ('FIXED','VARIABLE')),
  initial_amount NUMERIC NOT NULL,
  current_amount NUMERIC NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('ACTIVE','CANCELLED')),
  PRIMARY KEY (series_id),
  FOREIGN KEY (user_id) REFERENCES "user_profile"(user_id),
  FOREIGN KEY (account_id) REFERENCES "account"(account_id),
  FOREIGN KEY (counterparty_account_id) REFERENCES "account"(account_id),
  FOREIGN KEY (merchant_id) REFERENCES "merchant"(merchant_id),
  FOREIGN KEY (category_code) REFERENCES "category"(category_code)
);

CREATE TABLE "recurring_series_event" (
  event_id TEXT NOT NULL,
  series_id TEXT NOT NULL,
  event_type TEXT NOT NULL CHECK (event_type IN ('CREATED','AMOUNT_CHANGED','CANCELLED')),
  event_date TEXT NOT NULL,
  old_amount NUMERIC,
  new_amount NUMERIC,
  PRIMARY KEY (event_id),
  FOREIGN KEY (series_id) REFERENCES "recurring_series"(series_id)
);

CREATE TABLE "budget" (
  budget_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  category_code TEXT NOT NULL,
