);

CREATE TABLE "exception_case" (
  case_id TEXT NOT NULL,
  case_type TEXT NOT NULL CHECK (case_type IN ('TRANSFER_DOUBLE_COUNT','CREDIT_AS_PURCHASE','UNCATEGORIZED_HIGH_VALUE','BUDGET_CATEGORY_UNMAPPED','RECURRING_MISSED')),
